-- 2026-07-23 (WP-F3): PCPL hardening plan cleanup — 4 FIXED rows carrying forward
-- WP-R1/R3/T1 (time-freeze float snap, Rule-29 focal emphasis, THE EYE PCPL reveal
-- derivation) + 1 OPEN row (slider label staleness under choreography, deferred).
-- Generated by src/scripts/_seed_engine_bug_queue_wpf3_pcpl_hardening_cleanup.ts — idempotent.

INSERT INTO engine_bug_queue (bug_class, title, severity, owner_cluster, root_cause, prevention_rule, probe_type, probe_logic, status, concepts_affected, fixed_in_files, discovered_in_session, row_type) VALUES
('time_freeze_pin_float_precision_undershoot', 'SET_TIME_FREEZE catch-up accumulated float error, landing PM_simClockMs a hair below target — THE EYE’s poll never saw target reached and silently fell back to a non-deterministic capture', 'MAJOR', 'peter_parker:renderer_primitives', 'FIXED 2026-07-23 (WP-R1). The SET_TIME_FREEZE deterministic catch-up advanced PM_simClockMs by repeatedly adding 1000/60 per fixed step to reach the pinned target; because 1000/60 is not exactly representable in IEEE-754 float, N repeated additions accumulate rounding error, so a nominal target of 1000ms could land at e.g. 999.9999999999991 instead of exactly 1000. THE EYE’s capture poll waits for PM_simTimeMs >= target; a clock landing fractionally BELOW target due to float drift failed that comparison and silently fell back to a non-deterministic "capture anyway" path — defeating the entire purpose of the pin (a byte-identical frame). Fixed by snapping PM_simClockMs = Math.max(PM_simClockMs, PM_pinTargetMs) once the ceil-stepped catch-up loop completes, so the poll condition is satisfied by construction regardless of accumulated float error.', 'Any renderer catch-up/accumulator loop that must satisfy a ">=target" poll (THE EYE’s SET_TIME_FREEZE convergence check, or any future deterministic-pin mechanism) must snap-clamp the accumulator to the target with Math.max AFTER the step loop — never rely on N × (target/N) floating-point additions summing to exactly target. Reference: particle_field_renderer.ts’s own SET_TIME_FREEZE catch-up uses the same ceil-step + snap pattern; parametric_renderer.ts’s clock now mirrors it.', 'js_eval', 'After sending SET_TIME_FREEZE {at_ms: N} to a PCPL iframe and waiting one animation frame, read the exposed sim-clock value and assert it is >= N exactly (not merely "close to") — repeat for at least two different N values in the same session to catch residual per-call drift. Reference regression: scalar_vs_vector at_ms=1000/2000/3000 all read back >= target with zero fallback-path log lines.', 'FIXED', ARRAY['field_forces', 'contact_forces', 'normal_reaction', 'tension_in_string', 'hinge_force', 'free_body_diagram', 'vector_resolution', 'resultant_formula', 'direction_of_resultant', 'umbrella_tilt_angle', 'friction_static_kinetic', 'current_not_vector', 'pressure_scalar', 'scalar_vs_vector', 'vector_head_to_tail', 'newton_second_law_direction'], ARRAY['src/lib/renderers/parametric_renderer.ts'], 'session_2026-07-23_wpf3_pcpl_hardening_cleanup', 'incident'),
('pcpl_reveal_hold_unreachable_under_rule31', 'pcplRevealMs() summed the Rule-31-forbidden pause_after_ms field, so it always fell back to the 1500ms DEFAULT_REVEAL_MS floor — D7’s "reveal > 1500" relaxation was structurally unreachable on every correctly-authored PCPL state', 'MAJOR', 'peter_parker:visual_validator', 'FIXED 2026-07-23 (WP-T1, after WP-R5 locked the D5 choreography field names). deriveStateMeta.ts’s pcplRevealMs() derived a state’s reveal-complete time by summing tts_sentences[].pause_after_ms — a field Rule 31 explicitly FORBIDS authoring on new concepts (pause_after_ms/narrative_socratic are legacy-only). Every correctly-authored Rule-31 PCPL state therefore has zero pause_after_ms fields, so pcplRevealMs() always returned exactly DEFAULT_REVEAL_MS (1500ms) — meaning D7’s "reveal > 1500" relaxation branch could never fire for a compliant concept, false-failing D7 on any state whose scene_composition genuinely reveals/settles past 1500ms (e.g. a 3400ms once-sweep choreography). Fixed by adding pcplSceneRevealMs(state), deriving reveal timing from the scene’s OWN timeline instead — appear_at_ms+animate_in_ms, disappear_at_ms+fade_out_ms, animation.delay_sec/duration_sec, one rotate_continuous period, locus_trace.end_ms, and variable_choreography’s once-mode settle (including holds) — then the single PCPL fallback site takes Math.max(pcplRevealMs, pcplSceneRevealMs), which flows into both D7’s reveal_hold classification and frozen-pin target selection automatically. deriveMotionExpectations’ PCPL branch was extended alongside it so looping choreography/rotate_continuous marks motion=true (else D7 would separately demand stillness from a state that is deliberately still spinning).', 'THE EYE’s reveal-complete derivation for a Rule-31-compliant state must never depend SOLELY on a field Rule 31 forbids authoring (pause_after_ms) — any new PCPL choreography primitive with its own timeline (a new D5 addition, a future primitive type) must be added to pcplSceneRevealMs’s walk, not left to fall through to the DEFAULT_REVEAL_MS floor.', 'js_eval', 'For a PCPL state with zero tts_sentences[].pause_after_ms fields (the Rule-31-compliant case) but a scene_composition primitive whose settle time exceeds 1500ms, assert deriveStateMeta’s computed reveal value equals the scene-derived time (not the 1500ms floor) and that D7 passes rather than false-failing. Reference regression: scalar_vs_vector STATE_1 (phi_hook once-sweep, start 800 + dur 3400 + holds at 90°/270°) and STATE_4 (theta ping_pong) both previously false-failed D7 at exactly 1500ms and now clear it at their real scene-derived reveal time.', 'FIXED', ARRAY['field_forces', 'contact_forces', 'normal_reaction', 'tension_in_string', 'hinge_force', 'free_body_diagram', 'vector_resolution', 'resultant_formula', 'direction_of_resultant', 'umbrella_tilt_angle', 'friction_static_kinetic', 'current_not_vector', 'pressure_scalar', 'scalar_vs_vector', 'vector_head_to_tail', 'newton_second_law_direction'], ARRAY['src/lib/validators/visual/deriveStateMeta.ts'], 'session_2026-07-23_wpf3_pcpl_hardening_cleanup', 'incident'),
('pcpl_focal_pulse_scales_size_not_brightness', 'PM_focalPulseScale applied a ±12% SIZE pulse to the focal primitive (Rule 29 violation) — and premium_primitives.ts’s glow_focus scaled its halo RADIUS the same way', 'MODERATE', 'peter_parker:renderer_primitives', 'FIXED 2026-07-23 (WP-R3, plan design decision D3). PM_focalPulseScale computed a sinusoidal ±12% geometry SCALE factor applied to the focal primitive’s drawn size (arrow length, body radius, etc.) at 4 call sites, and premium_primitives.ts’s glow_focus primitive independently pulsed its halo RADIUS the same way — both violate Rule 29 ("emphasis is brightness, NEVER size — no zoom-in/zoom-out bulge on any element"). Replaced entirely (deleted, not stubbed — so any missed caller fails node --check loudly) with PM_focalEmphasis(spec), returning {isFocal, alphaMul, glowPx}: the focal primitive gets full alpha + a drawingContext.shadowBlur glow, non-focal peers dim to ~0.6 alpha — every geometry constant is left untouched. No PCPL concept was baseline-locked at the time of this fix, so the visual change (identical geometry, different brightness only) was a free window with zero baseline-regression risk.', 'Focal/emphasis treatment on any PCPL primitive (present or future) must route through PM_focalEmphasis’s {isFocal, alphaMul, glowPx} contract — alpha and drawingContext.shadowBlur only. Any new primitive type must NOT introduce its own ad-hoc size/radius pulse for emphasis; grep for PM_focalEmphasis before adding a new focal-treatment call site. Enforcement: `grep PM_focalPulseScale` across the renderer must always return zero matches — the function was deleted, not deprecated, specifically so a reintroduction is a loud, hard-to-miss event, not a silent revival.', 'js_eval', 'grep parametric_renderer.ts and premium_primitives.ts for PM_focalPulseScale — must return zero matches. Render two SET_TIME_FREEZE-pinned frames of the same focal state at t and t+500ms and assert every primitive’s geometry (position, length, radius) is byte-identical between them while alpha/shadowBlur may differ — any geometry delta between two pinned frames of a "focal pulse" state is a Rule 29 regression.', 'FIXED', ARRAY['field_forces', 'contact_forces', 'normal_reaction', 'tension_in_string', 'hinge_force', 'free_body_diagram', 'vector_resolution', 'resultant_formula', 'direction_of_resultant', 'umbrella_tilt_angle', 'friction_static_kinetic', 'current_not_vector', 'pressure_scalar', 'scalar_vs_vector', 'vector_head_to_tail', 'newton_second_law_direction'], ARRAY['src/lib/renderers/parametric_renderer.ts', 'src/lib/renderers/premium_primitives.ts'], 'session_2026-07-23_wpf3_pcpl_hardening_cleanup', 'incident'),
('pcpl_canvas_fixed_760x500_no_scale_to_fit', 'createCanvas(760,500) had no windowResized/scaling and no centering CSS — PCPL sims rendered pinned top-left in any larger review-panel container', 'MAJOR', 'peter_parker:renderer_primitives', 'FIXED 2026-07-23 (WP-R2, plan design decision D1). PCPL’s p5 sketch called createCanvas(760, 500) with no windowResized() handler and no centering CSS on the emitted iframe body, so in any container larger than the logical 760×500 coordinate space (the review site’s panel, a fullscreen player, a wide monitor) the canvas rendered pinned to the top-left corner with dead space filling the rest — founder-reported as half the review panel appearing empty. Fixed with PM_fitCanvas(): s = min(innerWidth/760, innerHeight/500), applied via canvas.style.width/height (a CSS style-based scale, NOT a CSS transform and NOT resizeCanvas) plus flex-centering in assembleParametricHtml’s emitted CSS; called from both setup() and p5’s windowResized(). Style-based sizing was specifically chosen because p5 1.9.4 divides mouse coordinates by canvas.scrollWidth/width internally — a CSS transform would have desynced mouse-to-canvas-coordinate mapping and silently broken every slider drag, whereas style-based width/height keeps p5’s own compensation correct with zero mouse-mapping code of our own. At exactly 760×500 (s=1) the fit is a no-op — zero pixel change, baseline-safe.', 'Any renderer that authors a fixed logical canvas size (PCPL’s 760×500 is mandated by every authored JSON’s pixel coordinates) must scale-to-fit via CSS style width/height + flex centering, never resizeCanvas (which would change the logical coordinate space the JSON was authored against) and never a CSS transform (which desyncs p5’s internal scrollWidth/width mouse-coordinate division). Call the fit function from both setup() and windowResized() so a browser resize or fullscreen toggle re-fits live.', 'manual', 'Render the same PCPL concept inside containers of 760×500 (must be pixel-identical to the pre-fit baseline) and three larger/odd sizes e.g. 1140×750 / 380×250 / 1200×500 (must render centered and aspect-locked, no top-left pinning, no distortion) — then verify a real slider drag at the scaled size still changes the underlying value (proves p5’s scrollWidth-based mouse compensation survived the style-based resize).', 'FIXED', ARRAY['field_forces', 'contact_forces', 'normal_reaction', 'tension_in_string', 'hinge_force', 'free_body_diagram', 'vector_resolution', 'resultant_formula', 'direction_of_resultant', 'umbrella_tilt_angle', 'friction_static_kinetic', 'current_not_vector', 'pressure_scalar', 'scalar_vs_vector', 'vector_head_to_tail', 'newton_second_law_direction'], ARRAY['src/lib/renderers/parametric_renderer.ts'], 'session_2026-07-23_wpf3_pcpl_hardening_cleanup', 'incident'),
('pcpl_slider_label_stale_under_choreography', 'drawCanvasSlider renders its knob/label purely from PM_sliderValues — never the live choreographed value pre-seizure — so a scripted slider visually reads a frozen default while the physics underneath correctly animates', 'MODERATE', 'peter_parker:renderer_primitives', 'NEW, OPEN — discovered 2026-07-23 during the WP-R5/WP-F1 choreography build-out; not fixed (out of the renderer WPs’ scope, left for the next renderer touch). drawCanvasSlider seeds and reads its knob position + numeric label EXCLUSIVELY from PM_sliderValues[spec.variable] (falling back to the JSON default), with no awareness of a state-level variable_choreography currently animating that same variable via PM_safeEval/lerp. Confirmed via code read: a ping-pong-driven θ slider (e.g. scalar_vs_vector STATE_4’s 0→180 sweep) has its arc/readout/arrow correctly driven by the live choreographed value each frame, but the ON-SCREEN SLIDER KNOB AND LABEL stay pinned at PM_sliderValues’ seeded default (e.g. a frozen "90°") until the teacher’s real mouse-drag first writes PM_sliderValues and seizes the ramp (per D5, seizure sets PM_userTouched[var] only inside the real-drag branch). Purely cosmetic — the taught physics (the actual drawn arc, arrow, and numeric HUD readout) renders correctly throughout; only the slider widget’s own knob/label lags.', 'Before a variable is seized (PM_userTouched[var] false), drawCanvasSlider should read its displayed knob position/label from the SAME live-choreographed value the rest of the scene uses for that variable, falling back to PM_sliderValues only once seized — mirroring the precedent already fixed for particle_field’s DOM slider labels under scripted ramps (the pf_slider_label_ignores_oneshot_lerp family; see combination_of_cells/meter_bridge sessions). Do not ship a NEW PCPL concept authoring variable_choreography on a slider-bound variable without either fixing this or explicitly hiding that slider row during the choreographed portion of the state (visible_controls precedent).', 'manual', 'For a state whose variable_choreography animates a variable that also has an on-screen slider (not yet seized), read the slider’s rendered numeric label at two different simulation clock times mid-ramp and assert it CHANGES to track the choreographed value — today it does not (stays at the JSON default) until a real drag seizes it. Reference repro: scalar_vs_vector STATE_4 theta ping_pong 0→180 — the arc/HUD sweep visibly while the θ slider knob/label stay frozen at the authored default until dragged.', 'OPEN', ARRAY['scalar_vs_vector'], ARRAY[]::text[], 'session_2026-07-23_wpf3_pcpl_hardening_cleanup', 'incident')
ON CONFLICT (bug_class) DO UPDATE SET status = EXCLUDED.status, root_cause = EXCLUDED.root_cause,
  prevention_rule = EXCLUDED.prevention_rule, probe_logic = EXCLUDED.probe_logic,
  title = EXCLUDED.title, severity = EXCLUDED.severity, owner_cluster = EXCLUDED.owner_cluster,
  concepts_affected = EXCLUDED.concepts_affected, fixed_in_files = EXCLUDED.fixed_in_files,
  fixed_at = CASE WHEN EXCLUDED.status = 'FIXED' THEN now() ELSE engine_bug_queue.fixed_at END;
